// Deviations: Original hub-only Edge log download limit and problem contract.

package container

// MaxEdgeLogsDownloadBytes bounds the hub's assembled log response; Direct streams unbounded.
const MaxEdgeLogsDownloadBytes = 64 << 20

// LogsDownloadProblem is generated by the hub, outside the agent contract fingerprint.
type LogsDownloadProblem struct {
	Code   string `json:"code" enum:"container.logs-too-large"`
	Status int    `json:"status"`
}

func (p *LogsDownloadProblem) Error() string  { return p.Code }
func (p *LogsDownloadProblem) GetStatus() int { return p.Status }
